-- Estrutura derivada do catálogo efetivamente recuperado. Sem jobs, defaults ou triggers de negócio.
BEGIN;
DO $$ BEGIN IF current_database()<>'donatella_preparacao' THEN RAISE EXCEPTION 'Destino recusado'; END IF; END $$;
SET LOCAL search_path=donatella_public,pg_catalog;
CREATE SCHEMA "donatella_public"; REVOKE ALL ON SCHEMA "donatella_public" FROM PUBLIC;
CREATE SCHEMA "donatella_auth"; REVOKE ALL ON SCHEMA "donatella_auth" FROM PUBLIC;
CREATE SCHEMA "donatella_storage"; REVOKE ALL ON SCHEMA "donatella_storage" FROM PUBLIC;
CREATE TYPE "donatella_auth"."aal_level" AS ENUM ('aal1','aal2','aal3');
CREATE TYPE "donatella_auth"."code_challenge_method" AS ENUM ('s256','plain');
CREATE TYPE "donatella_auth"."factor_status" AS ENUM ('unverified','verified');
CREATE TYPE "donatella_auth"."factor_type" AS ENUM ('totp','webauthn','phone','recovery_code');
CREATE TYPE "donatella_auth"."oauth_authorization_status" AS ENUM ('pending','approved','denied','expired');
CREATE TYPE "donatella_auth"."oauth_client_type" AS ENUM ('public','confidential');
CREATE TYPE "donatella_auth"."oauth_registration_type" AS ENUM ('dynamic','manual');
CREATE TYPE "donatella_auth"."oauth_response_type" AS ENUM ('code');
CREATE TYPE "donatella_auth"."one_time_token_type" AS ENUM ('confirmation_token','reauthentication_token','recovery_token','email_change_token_new','email_change_token_current','phone_change_token');
CREATE TYPE "donatella_public"."app_role" AS ENUM ('admin','user','sdr','support');
CREATE TYPE "donatella_public"."appointment_type" AS ENUM ('demo','meeting','support','followup');
CREATE TYPE "donatella_public"."conversation_status" AS ENUM ('nina','human','paused');
CREATE TYPE "donatella_public"."member_role" AS ENUM ('admin','manager','agent');
CREATE TYPE "donatella_public"."member_status" AS ENUM ('active','invited','disabled');
CREATE TYPE "donatella_public"."message_from" AS ENUM ('user','nina','human');
CREATE TYPE "donatella_public"."message_status" AS ENUM ('sent','delivered','read','failed','processing');
CREATE TYPE "donatella_public"."message_type" AS ENUM ('text','audio','image','document','video');
CREATE TYPE "donatella_public"."queue_status" AS ENUM ('pending','processing','completed','failed');
CREATE TYPE "donatella_public"."team_assignment" AS ENUM ('mateus','igor','fe','vendas','suporte');
CREATE TYPE "donatella_storage"."buckettype" AS ENUM ('STANDARD','ANALYTICS','VECTOR');
CREATE TABLE "donatella_auth"."users" ("id" uuid NOT NULL,"email" character varying(255),"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"banned_until" timestamp with time zone,"deleted_at" timestamp with time zone,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."appointments" ("id" uuid NOT NULL,"title" text NOT NULL,"description" text,"date" date NOT NULL,"time" time without time zone NOT NULL,"duration" integer NOT NULL,"type" "donatella_public"."appointment_type" NOT NULL,"attendees" text[],"contact_id" uuid,"meeting_url" text,"status" text,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,"metadata" jsonb,"user_id" uuid,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."automation_executions" ("id" uuid NOT NULL,"rule_id" uuid NOT NULL,"external_id" text NOT NULL,"target_signature" text NOT NULL,"event_id" uuid,"executed_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."automation_logs" ("id" uuid NOT NULL,"rule_id" uuid,"event_id" uuid,"status" text NOT NULL,"result" jsonb NOT NULL,"executed_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."automation_rules" ("id" uuid NOT NULL,"name" text NOT NULL,"trigger_topic" text NOT NULL,"filters" jsonb NOT NULL,"action_type" text NOT NULL,"action_config" jsonb NOT NULL,"active" boolean NOT NULL,"cooldown_hours" integer NOT NULL,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,"delay_minutes" integer NOT NULL,"cancel_if_changed" boolean NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."automation_scheduled" ("id" uuid NOT NULL,"rule_id" uuid NOT NULL,"event_id" uuid,"external_id" text,"target_signature" text,"payload" jsonb NOT NULL,"status_at_schedule" text,"scheduled_for" timestamp with time zone NOT NULL,"status" text NOT NULL,"cancel_reason" text,"executed_at" timestamp with time zone,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."contact_cooldowns" ("contact_phone" text NOT NULL,"rule_id" uuid NOT NULL,"last_sent_at" timestamp with time zone NOT NULL,PRIMARY KEY("contact_phone","rule_id"));
CREATE TABLE "donatella_public"."contacts" ("id" uuid NOT NULL,"phone_number" text NOT NULL,"whatsapp_id" text,"name" text,"call_name" text,"email" text,"profile_picture_url" text,"is_business" boolean,"is_blocked" boolean,"blocked_at" timestamp with time zone,"blocked_reason" text,"tags" text[],"notes" text,"client_memory" jsonb,"first_contact_date" timestamp with time zone NOT NULL,"last_activity" timestamp with time zone NOT NULL,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,"user_id" uuid,"company_name" text,"last_name" text,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."conversation_activities" ("id" uuid NOT NULL,"conversation_id" uuid NOT NULL,"contact_id" uuid NOT NULL,"title" text NOT NULL,"description" text,"activity_type" text NOT NULL,"scheduled_at" timestamp with time zone NOT NULL,"is_completed" boolean NOT NULL,"completed_at" timestamp with time zone,"reminder_sent" boolean NOT NULL,"created_by" uuid,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,"assigned_to" uuid,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."conversation_states" ("id" uuid NOT NULL,"conversation_id" uuid NOT NULL,"current_state" text NOT NULL,"last_action" text,"last_action_at" timestamp with time zone,"scheduling_context" jsonb,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."conversations" ("id" uuid NOT NULL,"contact_id" uuid NOT NULL,"status" "donatella_public"."conversation_status" NOT NULL,"is_active" boolean NOT NULL,"assigned_team" text,"assigned_user_id" uuid,"tags" text[],"nina_context" jsonb,"metadata" jsonb,"started_at" timestamp with time zone NOT NULL,"last_message_at" timestamp with time zone NOT NULL,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,"user_id" uuid,"queue" text NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."deal_activities" ("id" uuid NOT NULL,"deal_id" uuid NOT NULL,"type" text NOT NULL,"title" text NOT NULL,"description" text,"scheduled_at" timestamp with time zone,"completed_at" timestamp with time zone,"is_completed" boolean,"created_by" uuid,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."deals" ("id" uuid NOT NULL,"contact_id" uuid,"title" text NOT NULL,"company" text,"value" numeric,"stage" text,"priority" text,"tags" text[],"due_date" date,"owner_id" uuid,"notes" text,"lost_reason" text,"won_at" timestamp with time zone,"lost_at" timestamp with time zone,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"stage_id" uuid NOT NULL,"user_id" uuid,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."message_grouping_queue" ("id" uuid NOT NULL,"whatsapp_message_id" text NOT NULL,"phone_number_id" text NOT NULL,"message_data" jsonb NOT NULL,"contacts_data" jsonb,"processed" boolean NOT NULL,"created_at" timestamp with time zone NOT NULL,"process_after" timestamp with time zone,"message_id" uuid,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."message_processing_queue" ("id" uuid NOT NULL,"whatsapp_message_id" text NOT NULL,"phone_number_id" text NOT NULL,"raw_data" jsonb NOT NULL,"status" "donatella_public"."queue_status" NOT NULL,"priority" integer NOT NULL,"retry_count" integer NOT NULL,"error_message" text,"scheduled_for" timestamp with time zone,"processed_at" timestamp with time zone,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."messages" ("id" uuid NOT NULL,"conversation_id" uuid NOT NULL,"reply_to_id" uuid,"whatsapp_message_id" text,"type" "donatella_public"."message_type" NOT NULL,"from_type" "donatella_public"."message_from" NOT NULL,"content" text,"media_url" text,"media_type" text,"status" "donatella_public"."message_status" NOT NULL,"processed_by_nina" boolean,"nina_response_time" integer,"metadata" jsonb,"sent_at" timestamp with time zone NOT NULL,"delivered_at" timestamp with time zone,"read_at" timestamp with time zone,"created_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."nina_processing_queue" ("id" uuid NOT NULL,"message_id" uuid NOT NULL,"conversation_id" uuid NOT NULL,"contact_id" uuid NOT NULL,"context_data" jsonb,"status" "donatella_public"."queue_status" NOT NULL,"priority" integer NOT NULL,"retry_count" integer NOT NULL,"error_message" text,"scheduled_for" timestamp with time zone,"processed_at" timestamp with time zone,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."nina_settings" ("id" uuid NOT NULL,"is_active" boolean NOT NULL,"system_prompt_override" text,"test_system_prompt" text,"elevenlabs_api_key" text,"elevenlabs_voice_id" text NOT NULL,"elevenlabs_model" text,"elevenlabs_stability" numeric NOT NULL,"elevenlabs_similarity_boost" numeric NOT NULL,"elevenlabs_style" numeric NOT NULL,"elevenlabs_speaker_boost" boolean NOT NULL,"elevenlabs_speed" numeric,"whatsapp_access_token" text,"whatsapp_phone_number_id" text,"whatsapp_verify_token" text,"auto_response_enabled" boolean NOT NULL,"adaptive_response_enabled" boolean NOT NULL,"message_breaking_enabled" boolean NOT NULL,"response_delay_min" integer NOT NULL,"response_delay_max" integer NOT NULL,"timezone" text NOT NULL,"business_hours_start" time without time zone NOT NULL,"business_hours_end" time without time zone NOT NULL,"business_days" integer[] NOT NULL,"async_booking_enabled" boolean,"route_all_to_receiver_enabled" boolean NOT NULL,"test_phone_numbers" jsonb,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,"company_name" text,"sdr_name" text,"ai_model_mode" text,"audio_response_enabled" boolean,"ai_scheduling_enabled" boolean,"whatsapp_business_account_id" text,"user_id" uuid,"wc_webhook_secret" text,"wc_site_url" text,"wc_consumer_key" text,"wc_consumer_secret" text,"wc_products_enabled" boolean NOT NULL,"ai_provider" text NOT NULL,"ai_model" text,"ai_api_keys" jsonb NOT NULL,"out_of_hours_auto_reply" text,"out_of_hours_cooldown_minutes" integer NOT NULL,"support_alert_enabled" boolean NOT NULL,"support_alert_phone" text,"support_alert_template" text,"producao_user_id" uuid,"welcome_followup_enabled" boolean NOT NULL,"welcome_followup_minutes" integer NOT NULL,"welcome_followup_message" text NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."notifications" ("id" uuid NOT NULL,"type" text NOT NULL,"title" text NOT NULL,"body" text,"conversation_id" uuid,"contact_id" uuid,"metadata" jsonb NOT NULL,"is_read" boolean NOT NULL,"created_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."orders" ("id" uuid NOT NULL,"woo_order_id" bigint NOT NULL,"contact_id" uuid,"status" text,"total" numeric(12,2),"currency" text,"customer_id" bigint,"customer_email" text,"customer_phone" text,"customer_name" text,"payment_method" text,"payment_method_title" text,"is_first_order" boolean,"line_items" jsonb,"billing" jsonb,"raw_payload" jsonb,"order_created_at" timestamp with time zone,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,"last_processed_status" text,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."pipeline_stages" ("id" uuid NOT NULL,"title" text NOT NULL,"color" text NOT NULL,"position" integer NOT NULL,"is_system" boolean,"is_active" boolean,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"ai_trigger_criteria" text,"is_ai_managed" boolean,"user_id" uuid,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."product_catalog_audit" ("id" uuid NOT NULL,"conversation_id" uuid NOT NULL,"message_id" uuid,"media_url" text,"caption" text,"visual_analysis" jsonb NOT NULL,"searched_terms" text[] NOT NULL,"catalog_results" jsonb NOT NULL,"selected_product" jsonb,"confidence" numeric(5,4),"final_response" text,"handoff_requested" boolean NOT NULL,"status" text NOT NULL,"error_detail" text,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."profiles" ("id" uuid NOT NULL,"user_id" uuid NOT NULL,"full_name" text,"avatar_url" text,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."send_queue" ("id" uuid NOT NULL,"conversation_id" uuid NOT NULL,"contact_id" uuid NOT NULL,"message_type" text NOT NULL,"from_type" text NOT NULL,"content" text,"media_url" text,"metadata" jsonb,"status" "donatella_public"."queue_status" NOT NULL,"priority" integer NOT NULL,"retry_count" integer NOT NULL,"error_message" text,"scheduled_at" timestamp with time zone,"sent_at" timestamp with time zone,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,"message_id" uuid,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."support_cases" ("id" uuid NOT NULL,"conversation_id" uuid,"contact_id" uuid,"grupo_suporte" text NOT NULL,"categoria_suporte" text NOT NULL,"requer_agente_humano" boolean NOT NULL,"status_resolucao" text NOT NULL,"responsavel_id" uuid,"causa" text,"resumo" text,"sentimento" text,"order_number" text,"metadata" jsonb NOT NULL,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,"closed_at" timestamp with time zone,"closed_by" uuid,"resolution_note" text,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."system_settings" ("id" uuid NOT NULL,"registration_enabled" boolean NOT NULL,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."tag_definitions" ("id" uuid NOT NULL,"key" text NOT NULL,"label" text NOT NULL,"color" text NOT NULL,"category" text NOT NULL,"is_active" boolean NOT NULL,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,"user_id" uuid,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."team_business_hours" ("id" uuid NOT NULL,"team_id" uuid NOT NULL,"day_of_week" smallint NOT NULL,"is_open" boolean NOT NULL,"start_time" time without time zone NOT NULL,"end_time" time without time zone NOT NULL,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."team_functions" ("id" uuid NOT NULL,"name" text NOT NULL,"description" text,"is_active" boolean,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,"user_id" uuid,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."team_holidays" ("id" uuid NOT NULL,"team_id" uuid,"date" date NOT NULL,"name" text NOT NULL,"is_open" boolean NOT NULL,"start_time" time without time zone,"end_time" time without time zone,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."team_members" ("id" uuid NOT NULL,"name" text NOT NULL,"email" text NOT NULL,"role" "donatella_public"."member_role" NOT NULL,"status" "donatella_public"."member_status" NOT NULL,"avatar" text,"team_id" uuid,"function_id" uuid,"weight" integer,"last_active" timestamp with time zone,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,"user_id" uuid,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."teams" ("id" uuid NOT NULL,"name" text NOT NULL,"description" text,"color" text,"is_active" boolean,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,"user_id" uuid,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."user_roles" ("id" uuid NOT NULL,"user_id" uuid NOT NULL,"role" "donatella_public"."app_role" NOT NULL,"created_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."webhook_events" ("id" uuid NOT NULL,"topic" text NOT NULL,"payload" jsonb NOT NULL,"source" text NOT NULL,"received_at" timestamp with time zone NOT NULL,"processed" boolean NOT NULL,"error" text,"retry_count" integer NOT NULL,"next_retry_at" timestamp with time zone,"last_error_at" timestamp with time zone,"external_id" text,"event_signature" text,PRIMARY KEY("id"));
CREATE TABLE "donatella_public"."whatsapp_templates" ("id" uuid NOT NULL,"meta_template_id" text,"name" text NOT NULL,"category" text NOT NULL,"language" text NOT NULL,"components" jsonb NOT NULL,"samples" jsonb,"status" text NOT NULL,"quality_rating" text,"rejected_reason" text,"user_id" uuid,"created_at" timestamp with time zone NOT NULL,"updated_at" timestamp with time zone NOT NULL,PRIMARY KEY("id"));
CREATE TABLE "donatella_storage"."buckets" ("id" text NOT NULL,"name" text NOT NULL,"owner" uuid,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"public" boolean,"avif_autodetection" boolean,"file_size_limit" bigint,"allowed_mime_types" text[],"owner_id" text,"type" "donatella_storage"."buckettype" NOT NULL,"versioning_status" text NOT NULL,"lifecycle_configuration" jsonb,"lifecycle_configuration_generation" uuid,PRIMARY KEY("id"));
CREATE TABLE "donatella_storage"."objects" ("id" uuid NOT NULL,"bucket_id" text,"name" text,"owner" uuid,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"last_accessed_at" timestamp with time zone,"metadata" jsonb,"path_tokens" text[],"version" text,"owner_id" text,"user_metadata" jsonb,"archived_at" timestamp with time zone,"is_delete_marker" boolean NOT NULL,"is_versioned" boolean NOT NULL,PRIMARY KEY("id"));
CREATE TABLE atendimento_migracao.materializacao (execucao uuid NOT NULL,documento_id uuid NOT NULL,aplicado_em timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(execucao,documento_id),FOREIGN KEY(execucao,documento_id) REFERENCES atendimento_migracao.carga_documento(execucao,id));
CREATE TABLE atendimento_migracao.supervisao (id boolean PRIMARY KEY DEFAULT true CHECK(id),estado jsonb NOT NULL,atualizado_em timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON atendimento_migracao.materializacao,atendimento_migracao.supervisao FROM PUBLIC;
GRANT SELECT,INSERT,UPDATE ON atendimento_migracao.materializacao,atendimento_migracao.supervisao TO donatella_coletor;
CREATE ROLE donatella_consulta NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION;
GRANT CONNECT ON DATABASE donatella_preparacao TO donatella_consulta;
GRANT USAGE ON SCHEMA donatella_public,donatella_storage,atendimento_migracao TO donatella_consulta;
GRANT SELECT ON donatella_public.contacts,donatella_public.conversations,donatella_public.messages,donatella_public.profiles,donatella_storage.objects,atendimento_migracao.supervisao TO donatella_consulta;
CREATE INDEX consulta_conversas_contato ON donatella_public.conversations(contact_id,last_message_at DESC,id);
CREATE INDEX consulta_historico ON donatella_public.messages(conversation_id,created_at DESC,id);
CREATE INDEX consulta_anexos ON donatella_storage.objects(bucket_id,name);

GRANT USAGE ON SCHEMA "donatella_public" TO donatella_coletor; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA "donatella_public" TO donatella_coletor; REVOKE ALL ON ALL TABLES IN SCHEMA "donatella_public" FROM PUBLIC;
GRANT USAGE ON SCHEMA "donatella_auth" TO donatella_coletor; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA "donatella_auth" TO donatella_coletor; REVOKE ALL ON ALL TABLES IN SCHEMA "donatella_auth" FROM PUBLIC;
GRANT USAGE ON SCHEMA "donatella_storage" TO donatella_coletor; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA "donatella_storage" TO donatella_coletor; REVOKE ALL ON ALL TABLES IN SCHEMA "donatella_storage" FROM PUBLIC;
COMMIT;
